-- M3 inventory/channel foundation; cc_* only.
CREATE TABLE IF NOT EXISTS cc_inventory_skus (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,permanent_id CHAR(36) NOT NULL,legacy_product_id BIGINT UNSIGNED NULL,sku_code VARCHAR(120) NOT NULL,product_type VARCHAR(40) NOT NULL,configuration_snapshot LONGTEXT NOT NULL,actual_stock DECIMAL(18,3) NOT NULL DEFAULT 0,reserved_stock DECIMAL(18,3) NOT NULL DEFAULT 0,safety_stock DECIMAL(18,3) NOT NULL DEFAULT 0,sellable_stock DECIMAL(18,3) NOT NULL DEFAULT 0,in_transit_stock DECIMAL(18,3) NOT NULL DEFAULT 0,location VARCHAR(120) NULL,replenishment_date DATE NULL,publishable TINYINT(1) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'active',is_test TINYINT(1) NOT NULL DEFAULT 0,created_by_legacy_user_id INT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_sku_code(sku_code),UNIQUE KEY uq_cc_sku_pid(permanent_id),KEY idx_cc_sku_publish(publishable,status,sellable_stock)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_stock_reservations (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,inventory_sku_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,quantity DECIMAL(18,3) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',is_test TINYINT(1) NOT NULL DEFAULT 0,expires_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),KEY idx_cc_reservation_sku(inventory_sku_id,status),KEY idx_cc_reservation_order(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_channels (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,channel_code VARCHAR(60) NOT NULL,name VARCHAR(120) NOT NULL,adapter_status VARCHAR(30) NOT NULL DEFAULT 'not_configured',status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_channel_code(channel_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_channel_packages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,channel_id BIGINT UNSIGNED NOT NULL,inventory_sku_id BIGINT UNSIGNED NOT NULL,package_code VARCHAR(120) NOT NULL,public_title VARCHAR(190) NOT NULL,english_name VARCHAR(190) NOT NULL,public_parameters LONGTEXT NOT NULL,public_price DECIMAL(18,4) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'SGD',moq DECIMAL(18,3) NOT NULL DEFAULT 1,lead_time_days INT UNSIGNED NOT NULL DEFAULT 0,allow_order TINYINT(1) NOT NULL DEFAULT 0,inquiry_only TINYINT(1) NOT NULL DEFAULT 1,status VARCHAR(30) NOT NULL DEFAULT 'draft',is_test TINYINT(1) NOT NULL DEFAULT 0,created_by_legacy_user_id INT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_package_code(channel_id,package_code),KEY idx_cc_package_status(channel_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_publication_jobs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,channel_package_id BIGINT UNSIGNED NOT NULL,job_type VARCHAR(30) NOT NULL,check_snapshot LONGTEXT NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',attempts INT UNSIGNED NOT NULL DEFAULT 0,last_error VARCHAR(500) NULL,is_test TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),KEY idx_cc_publication_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
